  class << self
    def phase_div_hunt_v10553(code)
      PHASE_DIV_HUNT_MAPS_V10553[code.to_s.upcase]
    end

    def phase_div_challenge_v10553(code)
      PHASE_DIV_CHALLENGES_V10553[code.to_s.upcase]
    end

    def phase_div_species_v10553(species_key)
      k=species_key.to_s.downcase.gsub(/[^a-z0-9]+/,'_').to_sym
      PHASE_DIV_SPECIES_APPEARANCE_V10553[k]
    rescue
      nil
    end

    def phase_div_species_for_location_v10553(code)
      c=code.to_s.upcase
      out=[]
      PHASE_DIV_SPECIES_APPEARANCE_V10553.each do |k,row|
        out.push(k) if row[:first_location].to_s.upcase==c
      end
      out.sort{|a,b|PHASE_DIV_SPECIES_APPEARANCE_V10553[a][:appearance_order].to_i <=>
                     PHASE_DIV_SPECIES_APPEARANCE_V10553[b][:appearance_order].to_i}
    rescue
      []
    end

    def phase_div_authority_audit_v10553
      bad=[]
      rows=PHASE_DIV_SPECIES_APPEARANCE_V10553
      bad.push('species_count') unless rows.size==494
      dex=[];orders=[];hunt=0;reward=0;boss=0
      rows.each do |k,row|
        dex.push(row[:dex].to_i)
        orders.push(row[:appearance_order].to_i)
        bad.push('species_db:'+k.to_s) if defined?(SPECIES_DB_V016) && SPECIES_DB_V016[k]==nil
        first=row[:first_location].to_s.upcase
        natural=row[:natural_hunt].to_s.upcase
        unless PHASE_DIV_HUNT_MAPS_V10553.has_key?(first) || PHASE_DIV_CHALLENGES_V10553.has_key?(first)
          bad.push('first_location:'+k.to_s+':'+first)
        end
        bad.push('natural_hunt:'+k.to_s+':'+natural) unless PHASE_DIV_HUNT_MAPS_V10553.has_key?(natural)
        lv0=row[:level_min].to_i;lv1=row[:level_max].to_i
        bad.push('level:'+k.to_s) if lv0<1 || lv1<lv0 || lv1>100
        ai=row[:first_ai_tier]
        bad.push('ai:'+k.to_s) unless ai==nil || (ai.to_i>=0 && ai.to_i<=5)
        case row[:first_track].to_s
        when 'hunt';hunt+=1
        when 'challenge_reward';reward+=1
        when 'challenge_boss';boss+=1
        else;bad.push('track:'+k.to_s)
        end
      end
      bad.push('dex_unique') unless dex.uniq.size==494 && dex.min==1 && dex.max==494
      bad.push('order_unique') unless orders.uniq.size==494 && orders.min==1 && orders.max==494
      bad.push('track_count') unless hunt==446 && reward==12 && boss==36
      {:pass=>bad.empty?,:species=>rows.size,:hunt=>hunt,:challenge_reward=>reward,
       :challenge_boss=>boss,:hunts=>PHASE_DIV_HUNT_MAPS_V10553.size,
       :challenges=>PHASE_DIV_CHALLENGES_V10553.size,:bad=>bad}
    rescue
      {:pass=>false,:species=>0,:hunt=>0,:challenge_reward=>0,:challenge_boss=>0,
       :hunts=>0,:challenges=>0,:bad=>['audit_error']}
    end
  end
end

class Scene_PMD_AutoChess
  alias pmd_ac_v10553_start_battle start_battle unless method_defined?(:pmd_ac_v10553_start_battle)
  alias pmd_ac_v10553_focus_summary focus_cast_log_summary_v1055 unless method_defined?(:pmd_ac_v10553_focus_summary)

  def start_battle
    r=pmd_ac_v10553_start_battle
    begin
      @v10553_summary_logged=false
      if @phase==:battle && respond_to?(:verification_mode) && verification_mode==:normal &&
         !(respond_to?(:production_external_battle_fast_v10613?) && production_external_battle_fast_v10613?)
        a=PMD_AC.phase_div_authority_audit_v10553
        log_event(:battle,'BATTLE_PHASE_DIV_COLLECTION_CHALLENGE_AUTHORITY_V10553 START pass='+
          (a[:pass] ? '1':'0')+' species='+a[:species].to_i.to_s+'/494'+
          ' hunt_first='+a[:hunt].to_i.to_s+' challenge_reward='+a[:challenge_reward].to_i.to_s+
          ' challenge_boss='+a[:challenge_boss].to_i.to_s+
          ' hunt_maps='+a[:hunts].to_i.to_s+'/21 challenge_nodes='+a[:challenges].to_i.to_s+'/16'+
          ' hunt_ai=0..3 challenge_ai=1..5 level_cap=100 ui_visual_seal=deferred'+
          ' gameplay_change=0 errors=['+(a[:bad]||[]).join(',')+']')
      end
    rescue
    end
    r
  end

  def phase_div_authority_summary_v10553
    return false if @v10553_summary_logged
    @v10553_summary_logged=true
    a=PMD_AC.phase_div_authority_audit_v10553
    log_event(:battle,'BATTLE_PHASE_DIV_COLLECTION_CHALLENGE_AUTHORITY_SUMMARY_V10553 pass='+
      (a[:pass] ? '1':'0')+' species='+a[:species].to_i.to_s+'/494'+
      ' hunt_first='+a[:hunt].to_i.to_s+' fixed_reward='+a[:challenge_reward].to_i.to_s+
      ' legendary_boss='+a[:challenge_boss].to_i.to_s+
      ' maps='+a[:hunts].to_i.to_s+'+'+a[:challenges].to_i.to_s+
      ' random_map_bridge=next reward_materialization=next ui_polish=deferred blocking_gate=0')
    a[:pass]
  rescue
    false
  end

  def focus_cast_log_summary_v1055
    r=pmd_ac_v10553_focus_summary
    return r if respond_to?(:production_external_battle_fast_v10613?) && production_external_battle_fast_v10613?
    begin
      phase_div_authority_summary_v10553
    rescue
    end
    r
  end
end
